def add(self):
        """ Add a new VRF.
        """
        if self.vrf_id is None:
            raise ValueError('VRF ID is required')
        if self.vrf_name is None:
            raise ValueError('VRF Name is required')
        if self.vrf_description is None:
            raise ValueError('VRF Description is required')

        if self.vrf_id in self.vrfs:
            raise ValueError('VRF ID already exists')

        self.vrfs[self.vrf_id] = {
            'name': self.vrf_name,
            'description': self.vrf_description
        }

